insert into public.categories (slug, name, description, sort_order) values
('world','World News','Global affairs, diplomacy and international developments.',1),
('pakistan','Pakistan News','National stories from across Pakistan.',2),
('technology','Technology','Gadgets, AI, software and the digital economy.',3),
('business','Business','Markets, companies, startups and the economy.',4),
('sports','Sports','Cricket, football and sporting events worldwide.',5),
('entertainment','Entertainment','Film, music, television and culture.',6),
('health','Health','Medicine, wellness and public health.',7),
('education','Education','Schools, universities and learning.',8),
('science','Science','Discoveries, space and research.',9),
('lifestyle','Lifestyle','Food, fashion, home and everyday living.',10),
('travel','Travel','Destinations, guides and travel tips.',11);

with src(cat, slug, title, excerpt, img, alt, author, tags, feat, pick, brk, hours, intro, h1, p1, h2, p2, quote, h3, p3) as (values
('world','global-climate-summit-demo','Leaders Gather for a Landmark Climate Summit','A fictional summit explores how nations could coordinate on emissions, finance and adaptation.','1529107386315-e1a2ed48a620','Delegates seated around a large conference table','Sara Malik','{climate,diplomacy,summit}',true,false,true,2,
 'Delegates from dozens of nations convened this week in an illustrative scenario designed to show how a major climate summit is reported.','The agenda','Negotiators focused on three pillars: cutting emissions, financing clean energy in developing economies, and helping vulnerable regions adapt to extreme weather.','Finance takes centre stage','Much of the discussion centred on how wealthier economies could mobilise funding. Analysts in this example note that predictable, long-term commitments matter more than headline pledges.','Agreements only matter if they are measurable and enforced.','Reaction from observers','Civil society groups welcomed the dialogue but urged clearer timelines. Business leaders called for stable policy signals to unlock private investment.'),
('world','ceasefire-talks-progress-demo','Mediators Report Progress in Regional Ceasefire Talks','An illustrative look at how international mediation efforts unfold behind closed doors.','1521295121783-8a321d551ad2','World map pinned with markers','Daniel Hughes','{diplomacy,peace}',false,true,false,6,
 'In this demonstration report, mediators describe cautious optimism after several rounds of talks.','Steps on the table','Proposals include humanitarian corridors, prisoner exchanges and a phased withdrawal monitored by neutral observers.','Why timing matters','Diplomats emphasise that momentum can fade quickly, making confidence-building measures essential in the first weeks.','Trust is built one verified step at a time.','The road ahead','Further sessions are expected, with mediators stressing that any deal must be acceptable to communities on the ground.'),
('pakistan','lahore-heritage-restoration-demo','Restoration Project Breathes New Life into Historic Lahore Landmarks','A sample story on conservation work protecting centuries-old architecture.','1567157577867-05ccb1388e66','Historic mosque architecture in Lahore','Ayesha Khan','{lahore,heritage,culture}',true,true,false,3,
 'This demonstration article imagines a conservation programme focused on Lahore''s historic walled city.','Craftsmanship revived','Artisans trained in traditional fresco, tile and woodwork techniques are central to the effort, keeping rare skills alive.','Tourism and livelihoods','Local shopkeepers expect improved footfall as restored streets attract visitors, creating jobs in hospitality and guiding.','Heritage is not only about the past; it is an investment in the future.','Balancing old and new','Planners aim to modernise drainage and electricity while respecting the character of the old city.'),
('pakistan','karachi-public-transport-demo','Karachi Commuters Weigh In on New Bus Routes','An example of local reporting on urban mobility and commuter experiences.','1586339949916-3e9457bef6d3','Busy city street with traffic','Bilal Ahmed','{karachi,transport,cities}',false,false,true,9,
 'In this sample piece, commuters share early impressions of expanded bus services in Karachi.','Shorter journeys','Passengers report reduced waiting times on key corridors, though peak hours remain crowded.','Accessibility concerns','Advocates call for more ramps, clear signage and safer stops, especially for women and elderly riders.','A good transport system is measured by who it leaves behind.','What planners say','Officials in this scenario say feedback will shape the next phase of route planning.'),
('technology','ai-assistants-workplace-demo','How AI Assistants Are Reshaping the Modern Workplace','A demonstration explainer on productivity tools, risks and the skills workers need.','1677442136019-21780ecad995','Abstract artificial intelligence illustration','Omar Siddiqui','{ai,work,productivity}',true,true,false,1,
 'AI-powered assistants have moved from novelty to everyday tool. This sample article explains what that means for workers.','Where AI helps','Drafting emails, summarising documents and generating first-pass code are among the most common uses.','The risks','Accuracy, privacy and over-reliance remain real concerns. Organisations are writing policies on what data can be shared.','Treat AI output as a first draft, never the final word.','Skills that matter','Critical thinking, domain expertise and clear communication become more valuable, not less.'),
('technology','smartphone-battery-tips-demo','Seven Practical Ways to Extend Your Smartphone Battery Life','Simple, evidence-based habits that help your phone last longer every day.','1518770660439-4636190af475','Close-up of a circuit board','Hina Raza','{smartphones,tips,gadgets}',false,false,false,12,
 'Battery anxiety is common. This demonstration guide collects widely recommended habits.','Screen and display','Lower brightness, shorter screen timeout and dark mode on OLED screens can noticeably reduce drain.','Apps and background activity','Review which apps refresh in the background and restrict location access to when an app is in use.','Small settings changes add up to hours of extra use.','Charging habits','Avoid extreme heat and, where supported, enable optimised charging to slow long-term wear.'),
('business','markets-weekly-outlook-demo','Markets Weekly: What Investors Are Watching','A sample market roundup covering rates, earnings and currency moves.','1611974789855-9c2a0a7236a3','Stock market chart on a screen','Fatima Noor','{markets,stocks,economy}',false,true,true,4,
 'This illustrative roundup shows how a weekly market outlook is structured.','Interest rates','Central bank signals continue to dominate sentiment, with investors parsing every statement for hints on timing.','Earnings season','Company results will test whether profit margins can hold up as costs and consumer demand shift.','Volatility rewards patience more than prediction.','Currencies and commodities','Oil prices and the dollar remain key variables for emerging markets, including importers in South Asia.'),
('business','startup-funding-trends-demo','Startup Founders Adapt to a Tighter Funding Climate','An example feature on how young companies are prioritising profitability.','1460925895917-afdab827c52f','Laptop showing business analytics','Usman Tariq','{startups,funding,entrepreneurship}',false,false,false,15,
 'Founders interviewed for this demonstration feature describe a shift from rapid growth to sustainable growth.','Fewer, larger rounds','Investors are concentrating capital in companies with clear revenue and disciplined spending.','Creative financing','Revenue-based financing, grants and strategic partnerships are filling gaps left by venture capital.','Cash flow is the new growth metric.','Lessons for founders','Know your unit economics, keep runway long and communicate honestly with investors.'),
('sports','cricket-series-preview-demo','Series Preview: Young Talent Set to Shine in Upcoming Cricket Tour','A sample preview examining squads, conditions and players to watch.','1540747913346-19e32dc3e97e','Floodlit stadium filled with spectators','Ali Hassan','{cricket,preview}',true,false,true,5,
 'This demonstration preview looks ahead to a fictional cricket series between two well-matched sides.','Squad balance','Selectors have blended experienced openers with young pace bowlers who impressed in domestic cricket.','Conditions','Pitches are expected to offer early swing, making the new-ball battle decisive.','Series are often won in the first hour of each morning.','Players to watch','An uncapped leg-spinner and an aggressive middle-order batter could be the breakout stars.'),
('sports','football-tactics-pressing-demo','Explained: Why High Pressing Dominates Modern Football','A tactics explainer on pressing systems, risks and rewards.','1574629810360-7efbbe195018','Football on a green pitch','James Carter','{football,tactics}',false,true,false,20,
 'Pressing has become a defining feature of elite football. This sample explainer breaks it down.','How it works','Teams press in coordinated triggers, closing passing lanes to force errors high up the pitch.','The trade-offs','Pressing demands fitness and discipline; a single missed trigger can leave space behind the defence.','The best pressing teams defend by attacking.','Who does it best','Clubs with clear identities and long-serving coaches tend to execute pressing most consistently.'),
('entertainment','film-festival-highlights-demo','Film Festival Highlights: Stories That Stole the Spotlight','A demonstration roundup of standout films and emerging directors.','1489599849927-2ee91cede3ba','Cinema seats facing a screen','Zara Sheikh','{film,festival,cinema}',false,true,false,7,
 'This sample roundup captures the kind of coverage readers expect from a major film festival.','Breakout directors','First-time filmmakers dominated conversations with intimate, character-driven dramas.','Documentaries shine','Non-fiction films about climate, migration and music drew strong audience reactions.','Great cinema makes the personal feel universal.','Awards buzz','Critics expect several titles to feature in awards conversations later in the season.'),
('entertainment','music-streaming-concerts-demo','Live Music Returns with Record-Breaking Concert Season','An example story on touring, ticket prices and fan experiences.','1514525253161-7a46d19cd819','Crowd at a concert with stage lights','Hamza Iqbal','{music,concerts}',false,false,false,18,
 'Concert venues report strong demand in this demonstration piece on the live music economy.','Ticket demand','Fans are prioritising live experiences, though rising prices remain a concern.','Local artists benefit','Smaller venues say opening slots are helping regional artists reach bigger audiences.','Nothing replaces the energy of a live crowd.','Looking ahead','Promoters expect festival line-ups to be announced earlier as competition grows.'),
('health','heart-health-habits-demo','Five Daily Habits That Support a Healthier Heart','Evidence-informed lifestyle tips. Always consult a qualified doctor for advice.','1505751172876-fa1923c5c528','Stethoscope on a table','Dr. Nadia Farooq','{health,heart,wellness}',false,true,false,8,
 'Heart disease remains a leading cause of illness worldwide. This demonstration article summarises commonly recommended habits.','Move every day','Regular moderate activity, such as brisk walking, is widely recommended by health organisations.','Eat for your heart','Diets rich in vegetables, whole grains and pulses, with less salt and processed food, support heart health.','Small daily choices compound over a lifetime.','Check-ups matter','Routine blood pressure and cholesterol checks help catch problems early. This content is not medical advice.'),
('health','sleep-science-demo','The Science of Sleep: Why Rest Is Your Superpower','A sample explainer on sleep cycles, routines and common myths.','1576091160399-112ba8d25d1d','Doctor reviewing information','Dr. Kamran Ali','{sleep,health}',false,false,false,26,
 'Sleep affects memory, mood and immunity. This illustrative article explores why.','Sleep cycles','The night is divided into cycles of light, deep and REM sleep, each playing a different role.','Building a routine','Consistent bed and wake times, a dark room and limited screens before bed are commonly advised.','Sleep is not wasted time; it is maintenance time.','Myths to drop','Catching up on weekends does not fully reverse a week of short sleep.'),
('education','digital-classrooms-demo','Digital Classrooms: What Students and Teachers Really Think','A demonstration feature on blended learning in schools.','1503676260728-1c00da094a0b','Student studying with books','Maria Qureshi','{education,edtech,schools}',true,false,false,10,
 'Blended learning is becoming normal in many classrooms. This sample feature gathers perspectives.','Benefits','Teachers cite instant feedback and easier sharing of resources as major advantages.','Gaps remain','Reliable internet and devices are not universal, risking a widening divide between students.','Technology should amplify great teaching, not replace it.','What works','Short videos, interactive quizzes and project work were rated most engaging by students.'),
('education','scholarship-guide-demo','A Practical Guide to Applying for International Scholarships','Step-by-step tips for writing strong applications. Demonstration content.','1522202176988-66273c2fd55f','Students collaborating around a table','Saad Mirza','{scholarships,university,guide}',false,true,false,30,
 'Scholarships can open doors worldwide. This demonstration guide outlines a structured approach.','Start early','Many deadlines fall a year before courses begin, so build a calendar of target programmes.','The personal statement','Tell a specific story about your goals and how the programme helps you achieve them.','Specific beats impressive every time.','References and documents','Request recommendation letters early and keep certified copies of transcripts ready.'),
('science','mars-mission-demo','New Mission Aims to Search for Signs of Ancient Life on Mars','A sample science story on planetary exploration and its challenges.','1446776811953-b23d57bd21aa','View of Earth from space','Dr. Imran Shah','{space,mars,astronomy}',true,false,true,11,
 'In this illustrative report, scientists outline an ambitious plan to explore ancient Martian lakebeds.','Why lakebeds','Sediments formed in water are among the best places to look for preserved chemical traces of life.','Engineering hurdles','Landing safely, surviving dust storms and returning samples are among the toughest challenges.','Every mission answers a question and raises ten more.','International collaboration','Space agencies increasingly share instruments, data and costs.'),
('science','lab-breakthrough-batteries-demo','Researchers Explore Safer, Longer-Lasting Battery Materials','An example article on energy storage research.','1532094349884-543bc11b234d','Scientist working in a laboratory','Sana Javed','{research,energy,batteries}',false,false,false,22,
 'Better batteries could transform electric transport. This demonstration piece looks at the research.','Solid-state promise','Replacing liquid electrolytes with solids could reduce fire risk and increase energy density.','From lab to factory','Scaling production while keeping costs low remains the biggest obstacle.','The breakthrough is only half the story; manufacturing is the other half.','Timeline','Researchers caution that widespread commercial use may still take years.'),
('lifestyle','healthy-meal-prep-demo','Weekly Meal Prep Made Simple for Busy Families','A demonstration lifestyle guide to planning nutritious meals.','1490645935967-10de6ba17061','Bowls of fresh healthy food','Mehwish Anwar','{food,family,lifestyle}',false,true,false,14,
 'Meal prep saves time and money. This sample guide shows how to get started.','Plan the week','Choose three core dishes that can be mixed and matched across lunches and dinners.','Batch cook basics','Cook grains, lentils and roasted vegetables in bulk, then store them in portioned containers.','A little planning on Sunday saves hours during the week.','Keep it fresh','Add herbs, sauces and salads on the day to keep meals interesting.'),
('lifestyle','mindfulness-routine-demo','Building a Five-Minute Mindfulness Routine','Simple practices that fit into the busiest day. Demonstration content.','1506126613408-eca07ce68773','Person practising yoga outdoors','Rabia Hassan','{wellness,mindfulness}',false,false,false,28,
 'You do not need an hour to benefit from mindfulness. This sample article shows a short routine.','Breathe first','Spend one minute on slow breathing, counting four in and six out.','Body scan','Notice tension from head to toe, relaxing each area as you go.','Attention is a muscle; train it daily.','Make it stick','Attach the routine to an existing habit, such as your morning tea.'),
('travel','northern-areas-guide-demo','A Traveller''s Guide to Pakistan''s Northern Valleys','Planning tips for mountain journeys, seasons and responsible tourism.','1476514525535-07fb3b4ae5f1','Mountain lake surrounded by peaks','Kashif Baig','{travel,pakistan,mountains}',true,true,false,13,
 'Pakistan''s northern valleys are famous for dramatic landscapes. This demonstration guide helps you plan.','When to go','Late spring through early autumn usually offers the most accessible roads and mild weather.','Getting around','Hire experienced local drivers for mountain roads and allow extra days for weather delays.','Travel slowly; the mountains reward patience.','Travel responsibly','Carry reusable bottles, respect local customs and support community-run guesthouses.'),
('travel','budget-travel-tips-demo','Twelve Smart Ways to Travel More on a Smaller Budget','A demonstration guide to saving money without missing out.','1488646953014-85cb44e25828','Travel planning items with a map and camera','Nimra Saleem','{travel,budget,tips}',false,false,false,32,
 'Travel does not have to be expensive. This sample guide gathers practical ideas.','Be flexible','Shifting dates by a few days or flying mid-week can significantly reduce fares.','Stay local','Guesthouses and homestays often cost less and offer richer experiences.','The best souvenirs are stories, not things.','Eat like a local','Markets and street food stalls are budget-friendly and part of the adventure.')
)
insert into public.articles (slug, title, excerpt, content, cover_image, image_alt, category_id, author_name, tags, status, published_at, is_featured, is_editors_pick, is_breaking, is_demo, views)
select s.slug, s.title, s.excerpt,
  format(E'%s\n\n## %s\n\n%s\n\n## %s\n\n%s\n\n> %s\n\n## %s\n\n%s\n\n## Key takeaways\n\n- This article is **demonstration content** created to showcase the Info Spark''s layout.\n- Names, quotes and events are illustrative and should not be treated as real reporting.\n- Replace this sample with your own verified journalism from the admin dashboard.',
    s.intro, s.h1, s.p1, s.h2, s.p2, s.quote, s.h3, s.p3),
  'https://images.unsplash.com/photo-' || s.img || '?auto=format&fit=crop&w=1600&q=75',
  s.alt, c.id, s.author, s.tags::text[], 'published', now() - (s.hours || ' hours')::interval,
  s.feat, s.pick, s.brk, true, (50 + (random()*900)::int)
from src s join public.categories c on c.slug = s.cat;